import java.util.*;class NarrowRiverBendTest{public static void main(String[]a){List<RiverRibbon.Point> line=new ArrayList<>();for(int x=40;x<=960;x+=8)line.add(new RiverRibbon.Point(x,500,3.5,90));var free=RiverRibbon.smooth(line,83);double span=free.stream().mapToDouble(RiverRibbon.Point::z).max().orElseThrow()-free.stream().mapToDouble(RiverRibbon.Point::z).min().orElseThrow();if(span<40)throw new AssertionError("Narrow river lost bends: "+span);int n=128;float[] terrain=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)terrain[z*n+x]=100+Math.max(0,z*8-505)*3;var guided=RiverRibbon.smooth(line,83,terrain,n,8,1);double raw=free.stream().mapToDouble(p->Math.max(0,p.z()-505)).sum(),limited=guided.stream().mapToDouble(p->Math.max(0,p.z()-505)).sum();if(limited>raw*.15)throw new AssertionError("Meanders cut into raised terrain");if(guided.stream().anyMatch(p->Math.abs(p.radius()-3.5)>.001))throw new AssertionError("Bends widened channel");System.out.println("PASS: narrow channel retains broad bends (span="+span+") and limits displacement into rising terrain");}}
